import React from "react";
import { BrowserRouter as Router, Link } from "react-router-dom";
import Navbar from "./components/Navbar"; // Asegúrate de que Navbar.js está correctamente importado
import "./App.css";  // Si tienes algún archivo global de estilos

const App = () => {
  return (
    <Router>
      <Navbar />
      <div>
        {/* Sección de Inicio */}
        <section id="inicio">
          <h2>Bienvenido a nuestra página de inicio</h2>
          <p>Contenido de la sección de inicio...</p>
        </section>

        {/* Sección de Cursos */}
        <section id="cursos">
          <h2>Cursos</h2>
          <p>Contenido de la sección de cursos...</p>
        </section>

        {/* Sección de Sobre Nosotros */}
        <section id="sobre-nosotros">
          <h2>Sobre Nosotros</h2>
          <p>Contenido de la sección de sobre nosotros...</p>
        </section>

        {/* Sección de Contacto */}
        <section id="contacto">
          <h2>Contacto</h2>
          <p>Contenido de la sección de contacto...</p>
        </section>
      </div>
    </Router>
  );
};

export default App;
